import React from "react";
import { useNavigate } from "react-router-dom";

const categories = [
  {
    title: "Help Children",
    image:"data:image/jpeg;base64,"
  },
  {
    title: "Medical Support",
    image:  "data:image/jpeg;base64,"
  },
  {
    title: "Education Aid",
    image: "data:image/jpeg;base64,"
  },
  {
    title: "Emergency Help",
    image:  "data:image/jpeg;base64,"
  }
];

const FundCategories = () => {
  const navigate = useNavigate();

  const openCategory = (title) => {
    navigate(`/category/${encodeURIComponent(title)}`);
  };

  return (
    <div className="p-10">
      <h1 className="text-3xl font-bold text-center mb-8 text-[#007A8E]">
        Choose a Fundraising Category
      </h1>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {categories.map((cat, index) => (
          <div
            key={index}
            className="rounded-lg shadow-xl bg-white p-4 hover:scale-105 transition-transform cursor-pointer"
            onClick={() => openCategory(cat.title)}
          >
            <img
              src={cat.image}
              alt={cat.title}
              className="rounded-md h-40 w-full object-cover"
            />
            <h2 className="mt-4 font-bold text-lg">{cat.title}</h2>
          </div>
        ))}
      </div>
    </div>
  );
};

export default FundCategories;
